package forth

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

var numberRE = regexp.MustCompile(`^-?\d+$`)

type action func([]int) ([]int, error)

type wordDef struct {
	actions []action
}

var builtinActions = map[string]action{
	"+":    add,
	"-":    sub,
	"*":    mul,
	"/":    div,
	"dup":  dup,
	"drop": drop,
	"swap": swap,
	"over": over,
}

func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string]wordDef{}
	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if strings.ToLower(tokens[0]) == ":" {
			// word definition
			if len(tokens) < 4 || strings.ToLower(tokens[len(tokens)-1]) != ";" {
				return nil, fmt.Errorf("malformed definition %q", line)
			}
			name := strings.ToLower(tokens[1])
			if numberRE.MatchString(name) {
				return nil, fmt.Errorf("cannot redefine number %q", name)
			}
			actions, err := resolveTokens(tokens[2:len(tokens)-1], words)
			if err != nil {
				return nil, err
			}
			words[name] = wordDef{actions}
			continue
		}
		actions, err := resolveTokens(tokens, words)
		if err != nil {
			return nil, err
		}
		for _, a := range actions {
			stack, err = a(stack)
			if err != nil {
				return nil, err
			}
		}
	}
	return stack, nil
}

func resolveTokens(tokens []string, words map[string]wordDef) ([]action, error) {
	actions := make([]action, 0, len(tokens))
	for _, tok := range tokens {
		lower := strings.ToLower(tok)
		if numberRE.MatchString(tok) {
			n, err := strconv.Atoi(tok)
			if err != nil {
				return nil, err
			}
			actions = append(actions, func(s []int) ([]int, error) {
				return append(s, n), nil
			})
			continue
		}
		if w, ok := words[lower]; ok {
			// snapshot: capture the current definition's actions
			actions = append(actions, func(s []int) ([]int, error) {
				for _, a := range w.actions {
					var err error
					s, err = a(s)
					if err != nil {
						return nil, err
					}
				}
				return s, nil
			})
			continue
		}
		if f, ok := builtinActions[lower]; ok {
			actions = append(actions, f)
			continue
		}
		return nil, fmt.Errorf("undefined word %q", tok)
	}
	return actions, nil
}
