package forth

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// numberRE matches a signed integer literal: an optional minus sign
// followed by one or more ASCII digits.
var numberRE = regexp.MustCompile(`^-?[0-9]+$`)

// action transforms the data stack. It returns the new stack or an error.
type action func([]int) ([]int, error)

// wordDef is a user-defined word: an ordered list of actions.
type wordDef struct {
	actions []action
}

// builtinWords maps the built-in words to their actions.
var builtinWords = map[string]action{
	"+":    add,
	"-":    sub,
	"*":    mul,
	"/":    div,
	"dup":  dup,
	"drop": drop,
	"swap": swap,
	"over": over,
}

// Forth evaluates the given lines of Forth code and returns the final
// data stack.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string]wordDef{}
	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if strings.ToLower(tokens[0]) == ":" {
			if len(tokens) < 4 || strings.ToLower(tokens[len(tokens)-1]) != ";" {
				return nil, fmt.Errorf("malformed definition %q", line)
			}
			name := strings.ToLower(tokens[1])
			if numberRE.MatchString(name) {
				return nil, fmt.Errorf("cannot redefine number %q", name)
			}
			// Resolve the body against the dictionary as it is *before*
			// this definition is installed, so that redefining a word
			// later does not change the behavior of words that refer to
			// its earlier definition.
			actions, err := resolve(tokens[2:len(tokens)-1], words)
			if err != nil {
				return nil, err
			}
			words[name] = wordDef{actions: actions}
			continue
		}
		actions, err := resolve(tokens, words)
		if err != nil {
			return nil, err
		}
		for _, a := range actions {
			stack, err = a(stack)
			if err != nil {
				return nil, err
			}
		}
	}
	return stack, nil
}

// resolve converts tokens into actions. User-defined words take
// precedence over built-in words; both are looked up case-insensitively.
func resolve(tokens []string, words map[string]wordDef) ([]action, error) {
	actions := make([]action, 0, len(tokens))
	for _, tok := range tokens {
		if numberRE.MatchString(tok) {
			n, err := strconv.Atoi(tok)
			if err != nil {
				return nil, fmt.Errorf("invalid number %q", tok)
			}
			actions = append(actions, func(s []int) ([]int, error) {
				out := make([]int, len(s)+1)
				copy(out, s)
				out[len(s)] = n
				return out, nil
			})
			continue
		}
		lower := strings.ToLower(tok)
		if def, ok := words[lower]; ok {
			// Snapshot the current definition so that a later
			// redefinition of the same word does not alter this one.
			actions = append(actions, func(s []int) ([]int, error) {
				for _, a := range def.actions {
					var err error
					s, err = a(s)
					if err != nil {
						return nil, err
					}
				}
				return s, nil
			})
			continue
		}
		if f, ok := builtinWords[lower]; ok {
			actions = append(actions, f)
			continue
		}
		return nil, fmt.Errorf("undefined word %q", tok)
	}
	return actions, nil
}

